files.content:
:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #ef7d57;
  --border: #5d275d;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
}

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.invoice-card {
  background: var(--card);
  border: 4px solid var(--border);
  padding: 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 24px;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
}

h2 {
  font-size: 1.125rem;
  margin: 0 0 12px;
  color: var(--accent);
}

.field {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-row {
  display: flex;
  gap: 16px;
}

.field-row .field {
  flex: 1;
}

label {
  font-size: 0.875rem;
  color: var(--text);
}

input {
  font-family: var(--font);
  font-size: 1rem;
  padding: 8px 10px;
  border: 3px solid var(--border);
  background: #1a1c2c;
  color: var(--text);
  outline: none;
  width: 100%;
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: bold;
  padding: 10px 16px;
  background: var(--accent);
  color: #1a1c2c;
  border: 3px solid var(--border);
  cursor: pointer;
  width: 100%;
  transition: transform 0.05s, background 0.1s;
}

.btn:hover {
  background: var(--accent-dark);
}

.btn:active {
  transform: translate(2px, 2px);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.items-section {
  margin: 24px 0;
}

.empty-msg {
  font-size: 0.875rem;
  opacity: 0.7;
}

.items-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.items-list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-bottom: 2px dashed var(--border);
  font-size: 0.9375rem;
}

.items-list li .item-desc {
  flex: 1;
  word-break: break-word;
}

.items-list li .item-total {
  white-space: nowrap;
  color: var(--accent);
}

.totals {
  border-top: 4px solid var(--border);
  padding-top: 16px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 6px 0;
  font-size: 1rem;
}

.total-row input {
  width: 100px;
  text-align: right;
  padding: 4px 6px;
}

.grand-total {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--accent);
  border-top: 2px solid var(--border);
  margin-top: 8px;
  padding-top: 12px;
}

@media (max-width: 400px) {
  .invoice-card {
    padding: 16px;
  }
  .field-row {
    flex-direction: column;
    gap: 0;
  }
  .total-row input {
    width: 80px;
  }
}

(function () {
  'use strict';

  var items = [];

  var form = document.getElementById('item-form');
  var descInput = document.getElementById('desc');
  var qtyInput = document.getElementById('qty');
  var priceInput = document.getElementById('price');
  var taxInput = document.getElementById('tax-rate');
  var itemsList = document.getElementById('items-list');
  var emptyMsg = document.getElementById('empty-msg');
  var subtotalEl = document.getElementById('subtotal');
  var taxEl = document.getElementById('tax');
  var grandEl = document.getElementById('grand-total');

  function money(n) {
    return '$' + n.toFixed(2);
  }

  function round2(n) {
    return Math.round((n + Number.EPSILON) * 100) / 100;
  }

  function parsePositiveNumber(value) {
    var n = parseFloat(value);
    if (isNaN(n) || n < 0) return 0;
    return n;
  }

  function render() {
    itemsList.innerHTML = '';
    items.forEach(function (item) {
      var li = document.createElement('li');
      var desc = document.createElement('span');
      desc.className = 'item-desc';
      desc.textContent = item.desc + ' × ' + item.qty + ' @ ' + money(item.price);
      var total = document.createElement('span');
      total.className = 'item-total';
      total.textContent = money(item.total);
      li.appendChild(desc);
      li.appendChild(total);
      itemsList.appendChild(li);
    });
    emptyMsg.hidden = items.length > 0;

    var subtotal = items.reduce(function (sum, item) {
      return sum + item.total;
    }, 0);
    subtotal = round2(subtotal);

    var rate = parsePositiveNumber(taxInput.value);
    var tax = round2(subtotal * rate / 100);
    var grand = round2(subtotal + tax);

    subtotalEl.textContent = money(subtotal);
    taxEl.textContent = money(tax);
    grandEl.textContent = money(grand);
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var desc = descInput.value.trim();
    var qty = parsePositiveNumber(qtyInput.value);
    var price = parsePositiveNumber(priceInput.value);

    if (!desc) {
      descInput.focus();
      return;
    }
    if (qty <= 0) {
      qtyInput.focus();
      return;
    }

    var total = round2(qty * price);
    items.push({ desc: desc, qty: qty, price: price, total: total });
    descInput.value = '';
    qtyInput.value = '1';
    priceInput.value = '0.00';
    descInput.focus();
    render();
  });

  taxInput.addEventListener('input', render);

  render();
})();
